(function(){
  if (window.__lensInstalled__) return;
  window.__lensInstalled__ = true;
  var canvas = document.getElementById('cv');
  var ctx = canvas.getContext('2d');
  var pSlider = document.getElementById('pSlider'), pVal = document.getElementById('pVal');
  var fSlider = document.getElementById('fSlider'), fVal = document.getElementById('fVal');
  var out = document.getElementById('out');
  var playBtn = document.getElementById('playBtn');
  var scale = 6, anim = false, autoP = 60, autoDir = -1;
  window.simState = { P: 30, f: 10, Pp: 15, gamma: -0.5, atInfinity: false };
  function draw(){
    var P = parseFloat(pSlider.value), f = parseFloat(fSlider.value);
    if (anim) {
      autoP += autoDir * 0.5;
      if (autoP > 60) { autoP = 60; autoDir = -1; }
      if (autoP < 5) { autoP = 5; autoDir = 1; }
      P = autoP;
      pSlider.value = P;
    }
    var atInf = Math.abs(P - f) < 0.5;
    var Pp = atInf ? Infinity : P * f / (P - f);
    var gamma = atInf ? 0 : Pp / P;
    window.simState.P = P; window.simState.f = f; window.simState.Pp = isFinite(Pp) ? Pp : 0;
    window.simState.gamma = isFinite(gamma) ? gamma : 0; window.simState.atInfinity = atInf;
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.fillStyle = '#f8fafc'; ctx.fillRect(0, 0, canvas.width, canvas.height);
    ctx.strokeStyle = '#94a3b8'; ctx.lineWidth = 1; ctx.strokeRect(0.5, 0.5, canvas.width - 1, canvas.height - 1);
    var lx = 360, ly = 180;
    ctx.strokeStyle = '#475569'; ctx.lineWidth = 2;
    ctx.setLineDash([3, 3]);
    ctx.beginPath(); ctx.moveTo(40, ly); ctx.lineTo(680, ly); ctx.stroke();
    ctx.setLineDash([]);
    ctx.fillStyle = '#0f172a'; ctx.font = 'bold 12px sans-serif'; ctx.textAlign = 'center';
    ctx.fillText('F', lx - f * scale, ly + 16); ctx.fillText("F'", lx + f * scale, ly + 16);
    ctx.fillStyle = '#fff'; ctx.fillRect(lx - 2, ly - 40, 4, 80);
    ctx.strokeStyle = '#1d4ed8'; ctx.lineWidth = 2.5;
    ctx.beginPath(); ctx.moveTo(lx, ly - 40);
    ctx.lineTo(lx - 12, ly - 40 + 22); ctx.moveTo(lx, ly - 40);
    ctx.lineTo(lx + 12, ly - 40 + 22);
    ctx.beginPath(); ctx.moveTo(lx, ly + 40);
    ctx.lineTo(lx - 12, ly + 40 - 22); ctx.moveTo(lx, ly + 40);
    ctx.lineTo(lx + 12, ly + 40 - 22); ctx.stroke();
    ctx.fillStyle = '#1d4ed8'; ctx.font = 'bold 12px sans-serif';
    ctx.fillText('عدسة مقربة', lx, ly + 62);
    var objX = lx - P * scale, objH = 42;
    ctx.fillStyle = '#b91c1c'; ctx.fillRect(objX - 2, ly - objH, 4, objH);
    ctx.beginPath(); ctx.moveTo(objX - 2, ly - objH); ctx.lineTo(objX - 14, ly - objH + 10);
    ctx.lineTo(objX + 10, ly - objH + 10); ctx.fill();
    ctx.fillStyle = '#b91c1c'; ctx.font = 'bold 12px sans-serif';
    ctx.fillText('A', objX, ly + 18); ctx.fillText('B', objX, ly - objH - 8);
    if (atInf) {
      ctx.fillStyle = '#dc2626'; ctx.font = 'bold 15px sans-serif';
      ctx.fillText('الخيال في اللانهاية (P = f)', lx + 30, ly - 90);
    } else if (isFinite(Pp)) {
      var imgX = lx + Pp * scale;
      var imgH = objH * Math.abs(gamma);
      if (imgH < 2) imgH = 2;
      if (imgX > 30 && imgX < 690 && (ly + (gamma > 0 ? -imgH : imgH)) > 8 && (ly + (gamma > 0 ? -imgH : imgH)) < 340) {
        ctx.fillStyle = '#16a34a'; ctx.fillRect(imgX - 2, gamma > 0 ? ly - imgH : ly, 4, imgH);
        ctx.beginPath();
        ctx.moveTo(imgX - 2, gamma > 0 ? ly - imgH : ly + imgH);
        ctx.lineTo(imgX - 14, (gamma > 0 ? ly - imgH : ly + imgH) - 10);
        ctx.lineTo(imgX + 10, (gamma > 0 ? ly - imgH : ly + imgH) - 10); ctx.fill();
        ctx.fillStyle = '#16a34a'; ctx.font = 'bold 12px sans-serif';
        ctx.fillText("A'", imgX, ly + 18); ctx.fillText("B'", imgX, (gamma > 0 ? ly - imgH : ly + imgH) - 8);
      }
      ctx.strokeStyle = '#0ea5e9'; ctx.lineWidth = 1.5;
      ctx.beginPath(); ctx.moveTo(objX, ly - objH); ctx.lineTo(lx, ly - objH);
      ctx.lineTo(lx + (atInf ? 200 : Pp * scale), ly - objH); ctx.stroke();
      ctx.beginPath(); ctx.moveTo(objX, ly - objH); ctx.lineTo(lx, ly - objH);
      ctx.lineTo(lx + (atInf ? 200 : Pp * scale), ly - objH); ctx.stroke();
      ctx.strokeStyle = '#7c3aed'; ctx.lineWidth = 1.5;
      ctx.beginPath(); ctx.moveTo(objX, ly - objH); ctx.lineTo(lx, ly);
      ctx.lineTo(lx + (atInf ? 200 : Pp * scale), ly + (gamma < 0 ? imgH * 0.9 : -imgH * 0.9)); ctx.stroke();
    }
    pVal.textContent = P.toFixed(0); fVal.textContent = f.toFixed(0);
    if (atInf) out.textContent = 'P = f = ' + f.toFixed(0) + ' cm ⇒ الخيال في اللانهاية';
    else out.textContent = "P' = " + Pp.toFixed(1) + ' cm | γ = ' + gamma.toFixed(2) + ' | ' + (Pp > 0 ? 'خيال حقيقي مقلوب' : 'خيال وهمي معتدل') + (Math.abs(gamma) < 1 ? ' مصغّر' : (Math.abs(gamma) > 1 ? ' مكبّر' : ' بنفس الحجم'));
    window.simState.time = (window.simState.time || 0) + 0.05;
  }
  function loop(){ draw(); requestAnimationFrame(loop); }
  playBtn.addEventListener('click', function(){ anim = !anim; window.simState.animating = anim; playBtn.textContent = anim ? 'إيقاف حركة الجسم' : 'تشغيل حركة الجسم'; });
  function fit(){ canvas.style.maxWidth = '100%'; }
  if (!window.__fitInstalled__) { fit(); window.addEventListener('resize', fit); window.__fitInstalled__ = true; }
  loop();
})();
